import React, { useEffect, useState } from 'react';
//import { useParams } from 'react-router-dom';
import { Container, 
  Typography, 
  TextField, 
  CircularProgress,
  Grid,
  Box } from '@mui/material';



function ViewProfile() {
  
  const [user, setUser] = useState(null);
  const session = JSON.parse(sessionStorage.getItem('user'));

  useEffect(() => {
    fetch(`/api/v1/viewUser/${session._id}`)
      .then(response => response.json())
      .then(data => {
        setUser(data.data.user[0]); // Assuming data.data.user is an array with a single user object
      });
  }, [session]);

  if (!user) {
    return (
      <Container style={{ textAlign: 'center', marginTop: '20px' }}>
        <CircularProgress />
      </Container>
    );
  }

  // Handle form submit
  const handleSubmit = async (event) => {
    event.preventDefault();
    try {
      const response = await fetch(`/api/v1/updateUser/${session._id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formValues),
      });

      if (response.ok) {
        alert('Profile updated successfully');
      } else {
        alert('Error updating profile');
      }
    } catch (error) {
      alert('Error: ' + error.message);
    }
  };

  return (
    <Container>
      <Box sx={{ mt: 5 }}>
      <Typography variant="h4" gutterBottom>
        View User
      </Typography>
      </Box>
      <form onSubmit={handleSubmit}>
        <Grid container spacing={3}>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Username"
              value={user.userName}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Email"
              value={user.email}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Mobile Number"
              value={user.mobileNumber || 'N/A'}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="First Name"
              value={user.personalInfo?.firstName || 'N/A'}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Last Name"
              value={user.personalInfo?.lastName || 'N/A'}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Address"
              value={user.personalInfo?.address || 'N/A'}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Balance"
              value={user.accountInfo?.balance}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Currency"
              value={user.accountInfo?.currency}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Bank Code"
              value={user.accountInfo?.bankcode}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Wallet Address"
              value={user.accountInfo?.walletAddress}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Role"
              value={user.accountRoleInfo?.roleName}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          
        </Grid>
      </form>
    </Container>
  );
}

export default ViewProfile;
